import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { mkFixture, runCli } from './helpers.mjs';
import { MAP_LABEL, readMapText, sliceMap } from '../plugin/scripts/lib/map.mjs';

const SHA = 'a'.repeat(40);
const MAP_TEXT = `# Codebase map
<!-- dev-cycle map v1 head=${SHA}; generated by \`dev-cycle map\`, edit only ## Notes -->

## Root
- package manager: pnpm
- dirs: apps/, packages/

## Package apps/web
- name: web
- scripts: build, test

## Package packages/ui
- name: ui

## Notes

<!-- Maintained by discovery. -->
- \`apps/web/**\` — server actions live in app/actions
`;

function mk({ map = MAP_TEXT, lessons = true } = {}) {
  const files = {};
  const fx = mkFixture({ files });
  if (map !== null) fx.write('.dev-cycle/map.md', map);
  if (lessons) {
    const l = runCli(['lessons', 'add', '--globs', 'apps/web/**', '--text', 'Keep actions pure'], { cwd: fx.root });
    assert.equal(l.status, 0, l.stderr);
  }
  return fx;
}
const ctxList = (fx) => runCli(['lessons', 'list', '--touches', 'apps/web/**'], { cwd: fx.root }).stdout;

test('AC16: lessons, blank line, slice', () => {
  const fx = mk();
  try {
    const r = runCli(['context', '--touches', 'apps/web/**'], { cwd: fx.root });
    assert.equal(r.status, 0, r.stderr);
    const lessons = ctxList(fx);
    assert.ok(lessons.startsWith('Advisory rules'));
    const slice = sliceMap(readMapText(fx.root), ['apps/web/**']);
    assert.ok(slice.startsWith(MAP_LABEL) && slice.includes('## Package apps/web') && !slice.includes('packages/ui'));
    assert.equal(r.stdout, `${lessons}\n${slice.replace(/\n+$/, '')}\n`);
  } finally { fx.cleanup(); }
});

test('AC16: no map equals lessons list; no lessons gives slice only; neither is empty', () => {
  let fx = mk({ map: null });
  try {
    const r = runCli(['context', '--touches', 'apps/web/**'], { cwd: fx.root });
    assert.equal(r.status, 0);
    assert.equal(r.stdout, ctxList(fx));
  } finally { fx.cleanup(); }
  fx = mk({ lessons: false });
  try {
    const r = runCli(['context', '--touches', 'apps/web/**'], { cwd: fx.root });
    assert.equal(r.status, 0);
    assert.ok(r.stdout.startsWith(MAP_LABEL));
    assert.ok(!r.stdout.includes('Advisory'));
  } finally { fx.cleanup(); }
  fx = mk({ map: null, lessons: false });
  try {
    const r = runCli(['context', '--touches', 'apps/web/**'], { cwd: fx.root });
    assert.equal(r.status, 0);
    assert.equal(r.stdout, '');
  } finally { fx.cleanup(); }
});

test('AC17: context is read-only; --json shape; unknown option exits 2', () => {
  const fx = mk({ map: null });
  try {
    const r = runCli(['context', '--touches', 'apps/web/**'], { cwd: fx.root });
    assert.equal(r.status, 0);
    assert.ok(!fs.existsSync(path.join(fx.root, '.dev-cycle', 'map.md')));
    fx.write('.dev-cycle/map.md', MAP_TEXT);
    const before = fs.readFileSync(path.join(fx.root, '.dev-cycle', 'map.md'));
    const j = runCli(['context', '--touches', 'apps/web/**', '--json'], { cwd: fx.root });
    assert.equal(j.status, 0, j.stderr);
    const doc = JSON.parse(j.stdout);
    assert.deepEqual(Object.keys(doc).sort(), ['lessons', 'map']);
    assert.equal(doc.lessons[0].id, 'L1');
    assert.ok(doc.map.startsWith(MAP_LABEL));
    assert.ok(before.equals(fs.readFileSync(path.join(fx.root, '.dev-cycle', 'map.md'))));
    assert.equal(runCli(['context', '--bogus'], { cwd: fx.root }).status, 2);
  } finally { fx.cleanup(); }
});

test('R12: missing --touches means Root-only slice and no lessons', () => {
  const fx = mk();
  try {
    const r = runCli(['context'], { cwd: fx.root });
    assert.equal(r.status, 0);
    assert.ok(r.stdout.startsWith(MAP_LABEL) && !r.stdout.includes('Advisory') && !r.stdout.includes('## Package'));
  } finally { fx.cleanup(); }
});
